function initEnhancedCalendar(){const calendarEl=document.getElementById("calendar");if(!calendarEl)return;if(calendarEl.classList.contains("flatpickr-input")){calendarEl.classList.remove("flatpickr-input");}
if(calendarEl.hasAttribute("readonly")){calendarEl.removeAttribute("readonly");}
const existingFlatpickrCalendars=document.querySelectorAll(".flatpickr-calendar.animate.inline");existingFlatpickrCalendars.forEach((calendar)=>calendar.remove());let urlPath=window.location.pathname.replace(/^\//,"");let selectedDate=(function(){if(/\d{2}-\d{2}-\d{4}/.test(urlPath)){const[mm,dd,yyyy]=urlPath.split("-");return`${yyyy}-${mm}-${dd}`;}
return new Date().toISOString().split("T")[0];})();calendarEl.dataset.selectedDate=selectedDate;updateSelectedDateLabel(selectedDate);const calendar=new FullCalendar.Calendar(calendarEl,{initialView:"dayGridMonth",initialDate:selectedDate,headerToolbar:false,height:"auto",selectable:true,selectConstraint:{start:new Date().setHours(0,0,0,0),end:"2025-12-31",},events:function(info,successCallback){const startDate=new Date(info.start).toISOString().split("T")[0];const endDate=new Date(info.end).toISOString().split("T")[0];fetch(`/api/calendar_availability?start=${startDate}&end=${endDate}`).then((response)=>{if(!response.ok){throw new Error(`Calendar availability failed: ${response.status}`);}
return response.json();}).then((data)=>{const events=data.map((day)=>({title:"",start:day.date,allDay:true,display:"background",extendedProps:{availableRooms:day.availableRooms,totalRooms:day.totalRooms,reservationCount:day.reservationCount,occupancyPercentage:day.occupancyPercentage,},}));successCallback(events);}).catch((error)=>{console.error("Error fetching calendar availability:",error);successCallback([]);});},dayCellDidMount:function(info){if(info.date<new Date().setHours(0,0,0,0)){info.el.classList.add("fc-day-past");}
if(info.date.toISOString().split("T")[0]===selectedDate){info.el.classList.add("selected-date");}},eventDidMount:function(info){const event=info.event;const props=event.extendedProps;const dateStr=event.start.toISOString().split("T")[0];const availabilityIndicator=document.createElement("div");availabilityIndicator.className="availability-indicator";if(props.availableRooms===0){availabilityIndicator.classList.add("availability-none");}else if(props.availableRooms<props.totalRooms*0.3){availabilityIndicator.classList.add("availability-low");}else if(props.availableRooms<props.totalRooms*0.7){availabilityIndicator.classList.add("availability-medium");}else{availabilityIndicator.classList.add("availability-high");}
const dayCell=info.el.closest(".fc-daygrid-day");if(dayCell){dayCell.querySelector(".fc-daygrid-day-bg").appendChild(availabilityIndicator);if(props.reservationCount>0){const countBadge=document.createElement("div");countBadge.className="reservation-count";countBadge.textContent=props.reservationCount;dayCell.querySelector(".fc-daygrid-day-bg").appendChild(countBadge);}}},dateClick:function(info){if(info.date<new Date().setHours(0,0,0,0)){return;}
applySelectedDate(info.dateStr);},headerToolbar:{left:"",center:"title",right:"",},validRange:{start:new Date(),},titleFormat:{year:"numeric",month:"long"},dayHeaderFormat:{weekday:"short"},});calendar.render();console.info("[Calendar] Rendered with selected date",selectedDate);applySelectedDate(selectedDate,true);ensureDayCellTooltips();const calRoot=document.getElementById("calendar");if(calRoot){calRoot.addEventListener("click",function(e){const dayCell=e.target.closest(".fc-daygrid-day");if(!dayCell)return;if(dayCell.classList.contains("fc-day-disabled")||dayCell.classList.contains("fc-day-past"))
return;const date=dayCell.getAttribute("data-date");if(!date)return;applySelectedDate(date);});}
window.calendar=calendar;window.calendarEl=calendarEl;return calendar;}
function applySelectedDate(dateStr,skipCalendarSet){const calendarEl=document.getElementById("calendar");if(!calendarEl)return;calendarEl.dataset.selectedDate=dateStr;window.currentSelectedDate=dateStr;document.querySelectorAll(".fc-daygrid-day").forEach((d)=>d.classList.remove("selected-date"));const cell=document.querySelector(`.fc-daygrid-day[data-date="${dateStr}"]`);if(cell)cell.classList.add("selected-date");updateSelectedDateLabel(dateStr);updateRoomTimelines(dateStr);try{const d=new Date(dateStr+"T00:00:00");if(!isNaN(d.getTime())){const mm=String(d.getMonth()+1).padStart(2,"0");const dd=String(d.getDate()).padStart(2,"0");const yyyy=d.getFullYear();const newPath=`/${mm}-${dd}-${yyyy}`;if(window.location.pathname!==newPath){if(skipCalendarSet){window.history.replaceState({},"",newPath);}else{window.history.pushState({selectedDate:dateStr},"",newPath);}}}}catch(e){console.warn("URL path update failed",e);}
if(!skipCalendarSet&&window.calendar){window.calendar.gotoDate(dateStr);}}
function ensureDayCellTooltips(){if(typeof document==="undefined")return;const cells=document.querySelectorAll(".fc-daygrid-day");cells.forEach((cell)=>{try{if(cell.hasAttribute("title"))cell.removeAttribute("title");if(cell.hasAttribute("data-tooltip"))
cell.removeAttribute("data-tooltip");if(cell.classList.contains("day-title-tooltip"))
cell.classList.remove("day-title-tooltip");cell.dataset.tooltipBound="0";}catch(e){}});}
function updateSelectedDateLabel(dateStr){const el=document.getElementById("selected-date-label");if(!el)return;if(!dateStr)dateStr=new Date().toISOString().split("T")[0];const[y,m,d]=dateStr.split("-");el.textContent=`${m}-${d}-${y}`;}
window.applySelectedDate=applySelectedDate;window.updateSelectedDateLabel=updateSelectedDateLabel;function createTooltipContent(dateStr,props){const date=new Date(dateStr);const formattedDate=date.toLocaleDateString("en-US",{weekday:"long",month:"long",day:"numeric",});let content=`
        <div class="calendar-tooltip">
            <strong>${formattedDate}</strong>
    `;if(props.reservationCount>0){content+=`<p>${props.reservationCount} reservation${
      props.reservationCount !== 1 ? "s" : ""
    }</p>`;}else{content+=`<p>No reservations</p>`;}
content+=`<p>${props.availableRooms} of ${props.totalRooms} rooms available</p>`;content+=`<p>Occupancy: ${props.occupancyPercentage}%</p>`;content+=`</div>`;return content;}
document.addEventListener("DOMContentLoaded",function(){window.shiftMonth=function(offset){if(window.calendar){const selectedDate=window.currentSelectedDate||window.calendarEl?.dataset?.selectedDate||new Date().toISOString().split("T")[0];const[selectedYear,selectedMonth,selectedDay]=selectedDate.split("-").map(Number);const targetMonth=new Date(selectedYear,selectedMonth-1+offset,1);const y=targetMonth.getFullYear();const targetMonthIndex=targetMonth.getMonth();const m=String(targetMonthIndex+1).padStart(2,"0");const lastDayOfMonth=new Date(y,targetMonthIndex+1,0).getDate();const day=String(Math.min(selectedDay,lastDayOfMonth)).padStart(2,"0");applySelectedDate(`${y}-${m}-${day}`);}};const prevMonthBtn=document.getElementById("prev-month-btn");const nextMonthBtn=document.getElementById("next-month-btn");const todayBtn=document.getElementById("today-btn");if(prevMonthBtn)
prevMonthBtn.addEventListener("click",()=>window.shiftMonth(-1));if(nextMonthBtn)
nextMonthBtn.addEventListener("click",()=>window.shiftMonth(1));if(todayBtn)
todayBtn.addEventListener("click",()=>applySelectedDate(new Date().toISOString().split("T")[0]));initEnhancedCalendar();const observer=new MutationObserver(()=>{if(!document.querySelector("#calendar .fc-view-harness")&&document.getElementById("calendar")){console.warn("[Calendar] Lost internal markup, re-rendering");if(window.calendar){window.calendar.destroy();}
initEnhancedCalendar();}});const calRoot=document.getElementById("calendar");if(calRoot){observer.observe(calRoot,{childList:true});}});window.addEventListener("popstate",function(e){const path=window.location.pathname.replace(/^\//,"");if(/\d{2}-\d{2}-\d{4}/.test(path)){const[mm,dd,yyyy]=path.split("-");const iso=`${yyyy}-${mm}-${dd}`;applySelectedDate(iso,true);}});window.initEnhancedCalendar=initEnhancedCalendar;